use std::io::{Read,Write};use spore_core::{cell_feature_projection_v1::{project,Transform},cell_part_geometry::NativeCellPart};
fn w(s:&[u8],o:usize)->u32{u32::from_le_bytes(s[o..o+4].try_into().unwrap())}
fn main()->Result<(),Box<dyn std::error::Error>>{let args:Vec<_>=std::env::args().collect();if args.len()!=2{return Err("expected first or second".into())}let second=match args[1].as_str(){"first"=>false,"second"=>true,_=>return Err("bad side".into())};let mut data=Vec::new();std::io::stdin().read_to_end(&mut data)?;let size=if second{216}else{200};if data.len()!=6*size{return Err("bad corpus size".into())}let mut out=Vec::new();for c in data.chunks_exact(size){let off=if second{16}else{0};let a=&c[off..off+128];let r=&c[off+128..off+200];let row=NativeCellPart{word_06_is_ffff:false,class:2,center:[f32::from_bits(w(r,8)),f32::from_bits(w(r,12)),f32::from_bits(w(r,16))],matrix_bits:[0;9],radius:f32::from_bits(w(r,56)),tail_bits:[0;3]};let t=Transform{position:[w(a,0x4c),w(a,0x50),w(a,0x54)],scale:w(a,0x58),flags:a[0x48],matrix:std::array::from_fn(|i|w(a,0x5c+4*i))};let v=project(&row,t,second).map_err(|e|format!("{e:?}"))?;for x in v.center.into_iter().chain([v.radius]){out.extend(x.to_le_bytes())}}std::io::stdout().write_all(&out)?;Ok(())}
